{
  "command": "nohup ~/miniconda3/envs/mhd_claude/bin/python run_da.py da0_all L0 stereo_a,earth,solar_orbiter 5 comet 250 > ../../runs/da0_all.out 2>&1 &\necho launched",
  "description": "Launch the first DA experiment in background"
}

{
  "command": "cat /mnt/c/Users/cabot/OneDrive/Documents/Research/Cambridge/X3I/mhd_llm/shared_notes/20261016T232110Z_Argon_003.md | head -60; echo; cat /mnt/c/Users/cabot/OneDrive/Documents/Research/Cambridge/X3I/mhd_llm/claude/runs/da_log.txt",
  "description": "Read Argon's note and DA progress"
}

{
  "command": "cd /mnt/c/Users/cabot/OneDrive/Documents/Research/Cambridge/X3I/mhd_llm/claude/data/wsa_ccmc/enlil_run && ls -la; head -c 8 evo.3I-Atlas.nc | xxd | head -2; ~/miniconda3/envs/mhd_claude/bin/python -I -c "
import scipy.io as sio
f=sio.netcdf_file('evo.3I-Atlas.nc','r',mmap=False)
print(f.dimensions); 
for k,v in f.variables.items(): print(k, v.shape, getattr(v,'units',b''), getattr(v,'long_name',b''))
print({k:getattr(f,k) for k in list(f._attributes)[:30]})
"",
  "description": "Inspect the ENLIL evo netCDF at 3I/ATLAS"
}

{
  "command": "ls src/corona data/boundary data/boundary/qc 2>/dev/null | head -40; cat src/corona/README.md 2>/dev/null | head -30; sleep 1; cat runs/da_log.txt | tail -3",
  "description": "Check PFSS agent outputs and DA log"
}

{
  "command": "date -u +%H:%M:%S; ps aux | grep -E \"run_da|helio\" | grep -v grep | awk '{print $2, $3, $4, $10, substr($0, index($0,$11), 120)}'; tail -5 /mnt/c/Users/cabot/OneDrive/Documents/Research/Cambridge/X3I/mhd_llm/claude/runs/da0_all.out",
  "description": "Check DA process status"
}

{
  "command": "cd /mnt/c/Users/cabot/OneDrive/Documents/Research/Cambridge/X3I/mhd_llm/claude && timeout 400 bash -c 'until grep -q \"done da0_all\" runs/da_log.txt; do sleep 10; done'; tail -6 runs/da_log.txt",
  "description": "Wait for the DA run to finish",
  "timeout": 420000
}
